const chatResponse = await fetchApi.post({
    url: constants.Coze.URL_Chat,
    authorization: `${constants.Coze.Authorization}`,
    payload: {
        bot_id: constants.Coze.BotId,
        user_id: &#39;12312312313&#39;,
        query: &#39;你好&#39;,
        auto_save_history: true,
        stream: false,
        custom_variables: {
            custom_prompt: &#39;1+1&#39;,
        },
        additional_messages: [
            {
                role: &#39;user&#39;,
                content: &#39;你好&#39;, &#47;&#47; 必填
                content_type: &#39;text&#39;,
            },
        ],
    },
});
```

